#include <vector>
#include <stack>

using namespace std;

class Solution {
public:
    vector<int> canSeePersonsCount(vector<int>& heights) {
        vector<int> res(heights.size());
        stack<int> st;
        for (int i = heights.size() - 1; i >= 0; --i) {
            while (!st.empty() && heights[i] > st.top()) {
                st.pop();
                res[i]++;
            }
            if (!st.empty()) res[i]++;
            st.push(heights[i]);
        }
        return res;
    }
};
